@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        return http
            .csrf(csrf -> csrf.disable()) // REST API with JWT - no CSRF needed
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/auth/**").permitAll() // public endpoints
                .requestMatchers("/api/admin/**").hasRole("ADMIN")
                .anyRequest().authenticated() // all other endpoints require auth
            )
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS) // no server sessions
            )
            .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class) // JWT validation filter
            .build();
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(); // always hash passwords
    }
}

@Service
public class CustomUserDetailsService implements UserDetailsService {

    private final UserRepository userRepository;

    public CustomUserDetailsService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    @Override
    public UserDetails loadUserByUsername(String username) throws UsernameNotFoundException {
        var user = userRepository.findByUsername(username)
            .orElseThrow(() -> new UsernameNotFoundException("User not found: " + username));

        // Convert your entity to Spring Security's UserDetails
        return User.builder()
            .username(user.getUsername())
            .password(user.getPasswordHash()) // already BCrypt hashed in DB
            .roles(user.getRoles().toArray(new String[0])) // e.g. ["USER", "ADMIN"]
            .accountLocked(user.isLocked())
            .disabled(!user.isActive())
            .build();
    }
}

@RestController
@RequestMapping("/api/auth")
public class AuthController {

    private final AuthenticationManager authenticationManager;
    private final JwtTokenProvider jwtTokenProvider;

    public AuthController(AuthenticationManager authenticationManager,
                         JwtTokenProvider jwtTokenProvider) {
        this.authenticationManager = authenticationManager;
        this.jwtTokenProvider = jwtTokenProvider;
    }

    @PostMapping("/login")
    public LoginResponse login(@RequestBody LoginRequest request) {
        // Create unverified Authentication object with credentials
        var authToken = new UsernamePasswordAuthenticationToken(
            request.username(),
            request.password()
        );

        // AuthenticationManager validates credentials and returns authenticated object
        var authentication = authenticationManager.authenticate(authToken);

        // Generate JWT token for successfully authenticated user
        var jwt = jwtTokenProvider.generateToken(authentication);
        return new LoginResponse(jwt, authentication.getName());
    }
}

@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain jwtApiFilterChain(HttpSecurity http) throws Exception {
        return http
            .csrf(csrf -> csrf.disable()) // Safe: JWT in Authorization header
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)
            )
            .authorizeHttpRequests(auth -> auth
                .anyRequest().authenticated()
            )
            .addFilterBefore(jwtAuthFilter, UsernamePasswordAuthenticationFilter.class)
            .build();
    }

    // For traditional web apps with form login and cookies:
    @Bean
    public SecurityFilterChain webAppFilterChain(HttpSecurity http) throws Exception {
        return http
            .csrf(csrf -> csrf.csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse())) // CSRF enabled
            .formLogin(form -> form.loginPage("/login"))
            .authorizeHttpRequests(auth -> auth.anyRequest().authenticated())
            .build();
    }
}

@Configuration
@EnableWebSecurity // Optional in Spring Boot but explicit and recommended
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        return http
            .csrf(csrf -> csrf.disable())
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/public/**").permitAll()
                .anyRequest().authenticated()
            )
            .sessionManagement(session -> session
                .sessionCreationPolicy(SessionCreationPolicy.STATELESS)
            )
            .build();
    }

    // Without @EnableWebSecurity, this still works in Spring Boot
    // Auto-configuration detects spring-security on classpath
    // But adding it makes security configuration intent explicit

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}
